mapper.select:
SELECT b.id, b.building_code, b.road_address, b.jibun_address, b.bld_nm, b.dong_nm, b.pnu, b.latitude, b.longitude, b.sigungu_cd FROM building b WHERE b.latitude IS NOT NULL AND b.longitude IS NOT NULL AND b.latitude != 0 AND b.longitude != 0 AND ( SELECT COUNT(DISTINCT s.safe_category) FROM safety s WHERE s.building_id = b.id AND s.safe_category IN
#{category}
) < #{categoryCount} ORDER BY b.id LIMIT #{limit}

SELECT
c.safe_category,

COUNT(p.id) AS count_within500m,

CAST(
ROUND(
MIN(
ST_Distance_Sphere(
p.geom,
ST_SRID(
POINT(#{lng}, #{lat}),
4326
)
)
)
) AS SIGNED
) AS nearest_distance_meters

FROM (



    SELECT
    #{category} AS safe_category,
    (#{index} + 1) AS sort_order



) c

LEFT JOIN safety_poi p

ON p.category = c.safe_category

AND p.latitude
BETWEEN #{lat} - #{dlat}
AND #{lat} + #{dlat}

AND p.longitude
BETWEEN #{lng} - #{dlng}
AND #{lng} + #{dlng}

AND ST_Distance_Sphere(
p.geom,
ST_SRID(
POINT(#{lng}, #{lat}),
4326
)
) <= #{radius}

GROUP BY
c.safe_category,
c.sort_order

ORDER BY
c.sort_order

SELECT id

FROM safety

WHERE building_id = #{buildingId}
  AND safe_category = #{safeCategory}

SELECT

    COALESCE(
            NULLIF(TRIM(p.name), ''),
            p.category
    ) AS safe_name,

    p.latitude,

    p.longitude,

    CAST(
            ROUND(
                    ST_Distance_Sphere(
                            p.geom,
                            ST_SRID(
                                    POINT(#{lng}, #{lat}),
                                    4326
                            )
                    )
            ) AS SIGNED
    ) AS distance_m,

    CAST(p.polygon AS CHAR) AS polygon

FROM safety_poi p

WHERE p.category = #{category}

  AND p.latitude
    BETWEEN #{lat} - #{dlat}
    AND #{lat} + #{dlat}

  AND p.longitude
    BETWEEN #{lng} - #{dlng}
    AND #{lng} + #{dlng}

  AND ST_Distance_Sphere(
              p.geom,
              ST_SRID(
                      POINT(#{lng}, #{lat}),
                      4326
              )
      ) <= #{radius}

ORDER BY
    distance_m,
    p.id
